const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Moroto, Uganda location and 40 km radius
  const morotoCoords = [34.67, 1.65]; // [lon, lat]
  const morotoPoint = ee.Geometry.Point(morotoCoords);
  const buffer40km = morotoPoint.buffer(40000); // 40 km radius

  // 2. Helper function to calculate NDVI and mask clouds
  function getNDVICollection(startDate, endDate) {
    return ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(buffer40km)
      .filterDate(startDate, endDate)
      .map(function(img) {
        // Cloud masking using QA_PIXEL
        var cloudMask = img.select('QA_PIXEL').bitwiseAnd(32).eq(0)
          .and(img.select('QA_PIXEL').bitwiseAnd(64).eq(0));

        // Calculate NDVI: (NIR - Red) / (NIR + Red)
        var ndvi = img.normalizedDifference(['SR_B5', 'SR_B4'])
          .updateMask(cloudMask);
        return ndvi;
      });
  }

  // 3. Get August 2023 data
  const aug2023Col = getNDVICollection('2023-08-01', '2023-08-31');
  const aug2023Size = await aug2023Col.size().getInfo();

  if (aug2023Size === 0) {
    // Fallback to Landsat 7
    const aug2023ColL7 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
      .filterBounds(buffer40km)
      .filterDate('2023-08-01', '2023-08-31')
      .map(function(img) {
        var cloudMask = img.select('QA_PIXEL').bitwiseAnd(32).eq(0)
          .and(img.select('QA_PIXEL').bitwiseAnd(64).eq(0));
        var ndvi = img.normalizedDifference(['SR_B4', 'SR_B3']).updateMask(cloudMask);
        return ndvi;
      });
    const fallbackSize = await aug2023ColL7.size().getInfo();
    if (fallbackSize === 0) {
      print('August 2023 Images: 0');
      print('<answer>C1</answer>');
      return;
    }
  }

  // 4. Get historical August data (1991-2010)
  const historicalCol = getNDVICollection('1991-08-01', '2010-08-31');
  const historicalSize = await historicalCol.size().getInfo();

  if (historicalSize === 0) {
    print('Historical August (1991-2010) Images: 0');
    print('<answer>C1</answer>');
    return;
  }

  print(`August 2023 Images: ${aug2023Size}`);
  print(`August 1991-2010 Images: ${historicalSize}`);

  // 5. Calculate mean NDVI for August 2023
  const aug2023Mean = aug2023Col.mean();
  const aug2023Stats = await aug2023Mean
    .reduceRegion(
      ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
      buffer40km,
      1000,
      null,
      null,
      false,
      1e9
    ).getInfo();

  const ndvi2023 = aug2023Stats.nd ? aug2023Stats.nd : null;
  const count2023 = aug2023Stats['count'] ? aug2023Stats['count'] : 0;

  if (!ndvi2023 || isNaN(ndvi2023) || count2023 === 0) {
    print(`August 2023: No valid pixels (Count: ${count2023})`);
    print('<answer>C2</answer>');
    return;
  }

  // 6. Calculate mean NDVI for historical period
  const historicalMean = historicalCol.mean();
  const historicalStats = await historicalMean
    .reduceRegion(
      ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
      buffer40km,
      1000,
      null,
      null,
      false,
      1e9
    ).getInfo();

  const ndviHistorical = historicalStats.nd ? historicalStats.nd : null;
  const countHistorical = historicalStats['count'] ? historicalStats['count'] : 0;

  if (!ndviHistorical || isNaN(ndviHistorical) || countHistorical === 0) {
    print(`August 1991-2010: No valid pixels (Count: ${countHistorical})`);
    print('<answer>C2</answer>');
    return;
  }

  // 7. Validate NDVI ranges (-1 to 1)
  if (ndvi2023 < -1 || ndvi2023 > 1 || ndviHistorical < -1 || ndviHistorical > 1) {
    print(`Invalid NDVI values: 2023=${ndvi2023}, Historical=${ndviHistorical}`);
    print('<answer>C3</answer>');
    return;
  }

  // 8. Final comparison
  print(`August 2023 NDVI: ${ndvi2023.toFixed(4)} (Pixels: ${Math.round(count2023)})`);
  print(`August 1991-2010 NDVI: ${ndviHistorical.toFixed(4)} (Pixels: ${Math.round(countHistorical)})`);
  print(`Difference: ${(ndvi2023 - ndviHistorical).toFixed(4)}`);

  if (ndvi2023 < ndviHistorical) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
